using System;
using System.Reflection;
using System.Windows.Forms;
namespace Downfield {
public static class CatchMeterTests {
 static int checks,failures;static void Check(bool ok,string name){checks++;if(!ok){failures++;Console.WriteLine("FAIL Catch meter: "+name);}}
 static Simulation Throw(){Simulation s=new Simulation(120);s.Practice=true;s.NewGame();s.Playbook=2;s.Snap();for(int n=0;n<35;n++)s.Update(.02f,0,0);s.BeginPass(0);s.Charge=.1f;s.ReleasePass();return s;}
 static void Advance(Simulation s,float seconds,int fps){for(int n=0;n<(int)Math.Round(seconds*fps);n++)s.Update(1f/fps,0,0);}
 public static int Run(){checks=failures=0;Simulation s=Throw();s.AggressiveCatch();Advance(s,.15f,60);Check(s.CatchMeterValue==0&&!s.CatchMeterReady,"brief ready cue appears before cursor starts");Advance(s,.25f,60);Check(s.CatchMeterValue>.1f&&s.CatchMeterValue<.2f&&!s.CatchMeterLocked,"cursor is still in first fifth after four tenths of a second");Advance(s,.483333f,60);Check(Simulation.CatchChance(s.CatchMeterValue)==1,"green can be reached with a readable natural sweep");s.AggressiveCatch();float locked=s.CatchMeterValue;Check(s.CatchMeterLocked&&s.CatchGrade=="GREEN","second press locks the sampled value immediately");Advance(s,.4f,60);s.AggressiveCatch();Check(s.CatchMeterValue==locked&&s.CatchGrade=="GREEN","physics updates and extra presses cannot move a locked cursor");for(int n=0;n<300&&s.State==Phase.Flight;n++)s.Update(1f/60,0,0);Check(s.Completions==1&&s.CatchDisplayReceiver!=null,"result remains visible after the catch");Advance(s,1,60);Check(s.CatchDisplayReceiver==null,"result clears after its display window");
  float first=-1;foreach(int fps in new int[]{20,60,144}){s=Throw();s.AggressiveCatch();Advance(s,.9f,fps);if(first<0)first=s.CatchMeterValue;Check(Math.Abs(s.CatchMeterValue-first)<.012f,"real-time sweep is consistent at "+fps+" FPS");}
  s=Throw();BindingFlags flags=BindingFlags.NonPublic|BindingFlags.Instance;float duration=(float)typeof(Simulation).GetField("passDuration",flags).GetValue(s);typeof(Simulation).GetField("passTime",flags).SetValue(s,duration*.94f);s.AggressiveCatch();Advance(s,.9f,60);Check(s.State==Phase.Flight&&!s.CatchMeterLocked&&Simulation.CatchChance(s.CatchMeterValue)==1,"late activation still has time to see the meter and reach green");s.AggressiveCatch();Advance(s,.2f,60);Check(s.Completions==1,"late green resolves normally after locking");
  s=Throw();s.AggressiveCatch();Advance(s,2.5f,60);Check(s.CatchMeterLocked&&s.CatchGrade=="RED"&&s.CatchMeterValue==1&&s.State!=Phase.Flight,"unanswered meter ends at red instead of looping or hanging");
  s=Throw();Check(!s.CatchMeterActive,"ordinary passes do not activate slow catch timing");Advance(s,2.5f,60);Check(s.State!=Phase.Flight&&!s.CatchMeterActive,"normal catching completes without the meter");
  Input input=new Input();Check(input.CatchPadPress(Input.Y)&&!input.CatchPadPress(Input.Y),"held controller catch button produces only one edge");input.CatchPadPress(0);Check(input.CatchPadPress(Input.Y),"second physical press produces the stop edge");ControlBindings bindings=new ControlBindings();bindings.Controller.Find(b=>b.Action==Input.Y).Button=Input.X;bindings.Controller.Find(b=>b.Action==Input.X).Button=Input.Y;input=new Input();Check(input.CatchPadPress(bindings.TranslatePad(Input.X)),"remapped physical button still activates catch");input=new Input();input.SuppressPad=true;input.Context="flight";input.Bindings.Keyboard.Find(b=>b.Action==ControlBindings.Actions[22]).Key=Keys.H;input.KeysDown.Add(Keys.H);input.Poll();Check(input.CatchPressed,"keyboard catch edge is independent of prompt device selection");input.UsesController=true;Check(input.CatchPressed,"controller prompt selection does not discard a keyboard stop");
  Console.WriteLine("Catch meter: "+checks+" checks, "+failures+" failures");return failures;}
}
}
